INSERT INTO `bridge_task` (`id`,`title`,`description`,`status`,`created_at`,`updated_at`,`resolved_at`,`author_id`,`category_id`) VALUES (4,'È normale portare un regalo quando si viene invitati a cena in Italia?',CONVERT( USING utf8mb4),'open','2026-07-23 12:37:25','2026-07-23 14:27:21',NULL,1,4);
INSERT INTO `bridge_task` (`id`,`title`,`description`,`status`,`created_at`,`updated_at`,`resolved_at`,`author_id`,`category_id`) VALUES (5,'Come posso richiedere il codice fiscale dopo essere arrivato in Italia?',CONVERT( USING utf8mb4),'resolved','2026-07-23 13:16:03',NULL,'2026-07-23 13:18:24',5,3);
INSERT INTO `bridge_task` (`id`,`title`,`description`,`status`,`created_at`,`updated_at`,`resolved_at`,`author_id`,`category_id`) VALUES (7,'Vorrei visitare la Cina per la prima volta. Quale città mi consigliate?','Vorrei visitare la Cina per la prima volta, ma non conosco bene le diverse città. Vivo a Torino e mi interessano la cultura tradizionale, la cucina locale e i luoghi storici. Quale città mi consigliate per un primo viaggio e perché?🤗','open','2026-07-27 11:08:51',NULL,NULL,3,4);
INSERT INTO `bridge_task` (`id`,`title`,`description`,`status`,`created_at`,`updated_at`,`resolved_at`,`author_id`,`category_id`) VALUES (8,'Quali app si usano ogni giorno in Cina?','Vivo a Torino e sto organizzando un viaggio in Cina. In Italia usiamo spesso WhatsApp, Google Maps e Instagram. Quali sono le app più utilizzate in Cina per comunicare, pagare e spostarsi? Mi piacerebbe prepararmi prima della partenza.🙂','open','2026-07-27 12:28:16',NULL,NULL,8,5);
INSERT INTO `bridge_task` (`id`,`title`,`description`,`status`,`created_at`,`updated_at`,`resolved_at`,`author_id`,`category_id`) VALUES (9,'Quali piatti cinesi dovrei assolutamente provare?','Conosco solo ravioli e noodles, ma vorrei scoprire la vera cucina cinese. Quali piatti tipici mi consigliate? Mi piacciono sia i sapori delicati che quelli un po'' piccanti.😃','open','2026-07-27 12:29:20',NULL,NULL,8,4);
INSERT INTO `bridge_task` (`id`,`title`,`description`,`status`,`created_at`,`updated_at`,`resolved_at`,`author_id`,`category_id`) VALUES (10,'Questa frase in italiano è naturale?','Sto scrivendo un''e-mail a un professore italiano. Ho scritto: "Gentile Professore, vorrei chiederLe un''informazione riguardo all''esame." È una frase naturale? C''è un modo più cortese per esprimermi?💌','open','2026-07-27 12:34:48',NULL,NULL,2,1);
INSERT INTO `bridge_task` (`id`,`title`,`description`,`status`,`created_at`,`updated_at`,`resolved_at`,`author_id`,`category_id`) VALUES (11,'È normale salutare con due baci in Italia?','Sono uno studente cinese a Torino. Ho notato che molti italiani si salutano con due baci sulle guance. In quali situazioni è appropriato farlo? Ci sono differenze tra amici, colleghi e familiari?','open','2026-07-27 12:35:21',NULL,NULL,2,4);
INSERT INTO `bridge_task` (`id`,`title`,`description`,`status`,`created_at`,`updated_at`,`resolved_at`,`author_id`,`category_id`) VALUES (12,'Come rinnovo il permesso di soggiorno?','Il mio permesso di soggiorno scadrà tra due mesi. Vorrei sapere quando è meglio iniziare la procedura di rinnovo e quali documenti devo preparare. Qualcuno ha già fatto questa procedura?','open','2026-07-27 12:36:37',NULL,NULL,2,3);
INSERT INTO `bridge_task` (`id`,`title`,`description`,`status`,`created_at`,`updated_at`,`resolved_at`,`author_id`,`category_id`) VALUES (13,'Quali sono le principali differenze tra le università italiane e cinesi?','Studio in Italia da poco tempo e sono curioso di conoscere le differenze tra il sistema universitario italiano e quello cinese. Per esempio, il rapporto con i professori, gli esami e il metodo di studio.😊','open','2026-07-27 12:37:03',NULL,NULL,2,6);
INSERT INTO `bridge_task` (`id`,`title`,`description`,`status`,`created_at`,`updated_at`,`resolved_at`,`author_id`,`category_id`) VALUES (14,'Qual è il modo più economico per fare la spesa a Torino?','Vivo a Torino da pochi mesi. Vorrei sapere quali supermercati hanno un buon rapporto qualità-prezzo e se ci sono mercati locali dove acquistare frutta e verdura a prezzi convenienti.','open','2026-07-27 12:37:28',NULL,NULL,2,2);
INSERT INTO `bridge_task` (`id`,`title`,`description`,`status`,`created_at`,`updated_at`,`resolved_at`,`author_id`,`category_id`) VALUES (15,'Come fare amicizia con gli studenti italiani?','Sono uno studente cinese e all''inizio mi sento un po'' timido. Vorrei conoscere meglio gli studenti italiani e partecipare di più alla vita universitaria. Avete qualche consiglio?😂','open','2026-07-27 12:37:59',NULL,NULL,2,2);
