INSERT INTO `task_response` (`id`,`content`,`is_best_answer`,`created_at`,`updated_at`,`author_id`,`task_id`) VALUES (7,'Ciao! Io sono stato in Cina l''anno scorso e ti consiglio Shanghai. È una città moderna, ma ci sono anche quartieri storici come Yuyuan e il Bund. Inoltre è molto facile spostarsi con la metropolitana. Per una prima esperienza secondo me è perfetta.🤗',0,'2026-07-27 12:24:39',NULL,8,7);
INSERT INTO `task_response` (`id`,`content`,`is_best_answer`,`created_at`,`updated_at`,`author_id`,`task_id`) VALUES (8,'Ciao! Anch''io sono uno studente cinese a Torino. All''inizio ero molto timido, ma poi ho iniziato a partecipare ad alcune attività organizzate dall''università. È stato il modo migliore per conoscere studenti italiani. Ti consiglio di non avere paura di fare il primo passo!👍',0,'2026-07-27 12:49:39',NULL,5,15);
INSERT INTO `task_response` (`id`,`content`,`is_best_answer`,`created_at`,`updated_at`,`author_id`,`task_id`) VALUES (9,'Anch''io avevo lo stesso problema. Ho iniziato a parlare con gli studenti italiani durante i lavori di gruppo e le pause tra le lezioni. Piano piano è diventato tutto più naturale. Buona fortuna!',0,'2026-07-27 12:53:19',NULL,6,15);
INSERT INTO `task_response` (`id`,`content`,`is_best_answer`,`created_at`,`updated_at`,`author_id`,`task_id`) VALUES (10,'Ti consiglio anche di usare BuddyBridge! È un buon modo per conoscere studenti italiani con interessi simili e iniziare a parlare senza sentirsi troppo in imbarazzo.❤️',0,'2026-07-27 12:56:00',NULL,8,15);
