INSERT INTO `penpal_message` (`id`,`content`,`created_at`,`author_id`,`connection_id`,`is_read`,`subject`) VALUES (2,'Ciao Li Wei! Puoi aggiungere anche qualcosa sui tuoi interessi, così sarà più facile iniziare a parlare.','2026-07-23 12:17:02',1,1,1,'Re: Una presentazione');
INSERT INTO `penpal_message` (`id`,`content`,`created_at`,`author_id`,`connection_id`,`is_read`,`subject`) VALUES (3,'Mi piace ascoltare musica e visitare nuove città. Ho conservato il tuo esempio nel quaderno.','2026-07-23 12:19:25',2,1,1,'Re: Una presentazione');
INSERT INTO `penpal_message` (`id`,`content`,`created_at`,`author_id`,`connection_id`,`is_read`,`subject`) VALUES (4,'Ciao Li Wei! Anche io sto imparando italiano. Possiamo confrontare le espressioni che incontriamo ogni giorno.','2026-07-25 12:16:05',5,2,1,'Un saluto');
INSERT INTO `penpal_message` (`id`,`content`,`created_at`,`author_id`,`connection_id`,`is_read`,`subject`) VALUES (5,'Ciao! Quale musica ascolti di solito? Potremmo scambiarci una canzone italiana e una cinese.','2026-07-25 20:00:12',6,7,0,'Musica e lingue');
